@import "tailwindcss";
@import "tw-animate-css";
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');

@custom-variant dark (&:is(.dark *));

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

:root {
  --radius: 0.75rem;

  /* Font */
  --font-sans: 'Plus Jakarta Sans', sans-serif;

  /* Core Palette — deep indigo academic */
  --primary-hsl: 237 70% 50%;
  --primary-glow-hsl: 250 100% 70%;
  --accent-hsl: 197 80% 45%;
  --success-hsl: 152 60% 40%;
  --warning-hsl: 38 95% 55%;
  --danger-hsl: 0 75% 55%;

  /* Backgrounds */
  --background: oklch(0.978 0.004 264);
  --foreground: oklch(0.15 0.02 264);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.15 0.02 264);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.15 0.02 264);

  /* Primary — indigo */
  --primary: oklch(0.45 0.22 264);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.94 0.012 264);
  --secondary-foreground: oklch(0.3 0.04 264);

  --muted: oklch(0.94 0.008 264);
  --muted-foreground: oklch(0.52 0.02 264);

  --accent: oklch(0.93 0.02 197);
  --accent-foreground: oklch(0.25 0.08 197);

  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.9 0.01 264);
  --input: oklch(0.92 0.01 264);
  --ring: oklch(0.55 0.18 264);

  /* Charts */
  --chart-1: oklch(0.45 0.22 264);
  --chart-2: oklch(0.58 0.16 197);
  --chart-3: oklch(0.55 0.18 152);
  --chart-4: oklch(0.65 0.19 84);
  --chart-5: oklch(0.62 0.21 30);

  /* Sidebar — deep indigo */
  --sidebar: oklch(0.26 0.1 264);
  --sidebar-foreground: oklch(0.92 0.02 264);
  --sidebar-primary: oklch(0.7 0.18 264);
  --sidebar-primary-foreground: oklch(0.15 0.02 264);
  --sidebar-accent: oklch(0.35 0.1 264);
  --sidebar-accent-foreground: oklch(0.95 0.01 264);
  --sidebar-border: oklch(0.38 0.08 264);
  --sidebar-ring: oklch(0.55 0.18 264);

  /* Custom tokens */
  --gradient-primary: linear-gradient(135deg, oklch(0.45 0.22 264), oklch(0.55 0.22 250));
  --gradient-hero: linear-gradient(135deg, oklch(0.26 0.1 264) 0%, oklch(0.35 0.14 250) 100%);
  --gradient-card-indigo: linear-gradient(135deg, oklch(0.45 0.22 264), oklch(0.52 0.2 250));
  --gradient-card-teal: linear-gradient(135deg, oklch(0.48 0.16 197), oklch(0.55 0.14 185));
  --gradient-card-green: linear-gradient(135deg, oklch(0.5 0.15 152), oklch(0.56 0.13 140));
  --gradient-card-amber: linear-gradient(135deg, oklch(0.62 0.18 84), oklch(0.68 0.16 70));
  --gradient-card-rose: linear-gradient(135deg, oklch(0.55 0.2 30), oklch(0.62 0.18 18));
  --shadow-card: 0 1px 3px oklch(0 0 0 / 0.06), 0 4px 12px oklch(0.45 0.22 264 / 0.08);
  --shadow-elevated: 0 4px 20px oklch(0.45 0.22 264 / 0.15);
  --transition-smooth: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-sans);
    font-weight: 700;
  }
}

@layer utilities {
  .gradient-primary { background: var(--gradient-primary); }
  .gradient-hero { background: var(--gradient-hero); }
  .gradient-card-indigo { background: var(--gradient-card-indigo); }
  .gradient-card-teal { background: var(--gradient-card-teal); }
  .gradient-card-green { background: var(--gradient-card-green); }
  .gradient-card-amber { background: var(--gradient-card-amber); }
  .gradient-card-rose { background: var(--gradient-card-rose); }
  .shadow-card { box-shadow: var(--shadow-card); }
  .shadow-elevated { box-shadow: var(--shadow-elevated); }
  .transition-smooth { transition: var(--transition-smooth); }

  .stat-card-colored {
    @apply rounded-xl p-5 text-white relative overflow-hidden;
    box-shadow: var(--shadow-elevated);
  }
  .stat-card-colored::before {
    content: '';
    position: absolute;
    top: -40%;
    right: -20%;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: oklch(1 0 0 / 0.08);
  }
  .stat-card-colored::after {
    content: '';
    position: absolute;
    bottom: -30%;
    left: -10%;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: oklch(1 0 0 / 0.05);
  }
}

