import { useEffect, useState } from 'react';
import { LivingAppsService } from '@/services/livingAppsService';
import type { Dozenten, Teilnehmer, Raeume, Kurse, Anmeldungen } from '@/types/app';
import { format, isAfter, isBefore, parseISO } from 'date-fns';
import { de } from 'date-fns/locale';
import {
  BookOpen,
  CalendarCheck,
  CreditCard,
  DoorOpen,
  GraduationCap,
  TrendingUp,
  Users,
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Link } from 'react-router-dom';

interface Stats {
  dozenten: Dozenten[];
  teilnehmer: Teilnehmer[];
  raeume: Raeume[];
  kurse: Kurse[];
  anmeldungen: Anmeldungen[];
  loading: boolean;
}

function ColoredStatCard({
  label,
  value,
  sub,
  icon: Icon,
  gradient,
  href,
}: {
  label: string;
  value: string | number;
  sub: string;
  icon: React.ElementType;
  gradient: string;
  href: string;
}) {
  return (
    <Link to={href} className="block group">
      <div className={`stat-card-colored ${gradient} transition-smooth group-hover:scale-[1.02]`}>
        <div className="relative z-10 flex items-start justify-between">
          <div>
            <p className="text-sm font-medium opacity-85">{label}</p>
            <p className="text-3xl font-800 mt-1 tracking-tight">{value}</p>
            <p className="text-xs opacity-70 mt-1">{sub}</p>
          </div>
          <div className="bg-white/15 rounded-xl p-2.5">
            <Icon size={22} />
          </div>
        </div>
      </div>
    </Link>
  );
}

function UpcomingKurseCard({ kurse, dozenten }: { kurse: Kurse[]; dozenten: Dozenten[] }) {
  const today = new Date();
  const upcoming = kurse
    .filter((k) => k.fields.startdatum && isAfter(parseISO(k.fields.startdatum), today))
    .sort((a, b) => (a.fields.startdatum! > b.fields.startdatum! ? 1 : -1))
    .slice(0, 5);

  const dozentenMap = new Map(dozenten.map((d) => [d.record_id, d.fields.name]));

  const statusColor: Record<string, string> = {
    geplant: 'bg-amber-100 text-amber-700',
    aktiv: 'bg-green-100 text-green-700',
    abgeschlossen: 'bg-slate-100 text-slate-600',
    abgesagt: 'bg-red-100 text-red-700',
  };
  const statusLabel: Record<string, string> = {
    geplant: 'Geplant',
    aktiv: 'Aktiv',
    abgeschlossen: 'Abgeschlossen',
    abgesagt: 'Abgesagt',
  };

  return (
    <div className="bg-card rounded-xl shadow-card p-6">
      <div className="flex items-center justify-between mb-5">
        <h3 className="text-base font-700 text-foreground">Bevorstehende Kurse</h3>
        <Link to="/kurse" className="text-xs text-primary font-600 hover:underline">
          Alle anzeigen →
        </Link>
      </div>
      {upcoming.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-6">Keine bevorstehenden Kurse</p>
      ) : (
        <div className="space-y-3">
          {upcoming.map((kurs) => {
            const dozentId = kurs.fields.dozent
              ? kurs.fields.dozent.match(/([a-f0-9]{24})$/i)?.[1]
              : null;
            const dozentName = dozentId ? dozentenMap.get(dozentId) : null;
            const status = kurs.fields.status ?? 'geplant';
            return (
              <div
                key={kurs.record_id}
                className="flex items-center gap-4 p-3 rounded-lg bg-muted/50 hover:bg-muted transition-smooth"
              >
                <div className="flex-shrink-0 w-10 h-10 gradient-card-indigo rounded-lg flex items-center justify-center">
                  <BookOpen size={16} className="text-white" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-600 truncate">{kurs.fields.titel}</p>
                  <p className="text-xs text-muted-foreground">
                    {kurs.fields.startdatum
                      ? format(parseISO(kurs.fields.startdatum), 'dd. MMM yyyy', { locale: de })
                      : '—'}
                    {dozentName ? ` · ${dozentName}` : ''}
                  </p>
                </div>
                <span
                  className={`text-xs px-2 py-0.5 rounded-full font-500 flex-shrink-0 ${statusColor[status]}`}
                >
                  {statusLabel[status]}
                </span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function AnmeldungenStatusCard({ anmeldungen }: { anmeldungen: Anmeldungen[] }) {
  const bezahlt = anmeldungen.filter((a) => a.fields.bezahlt === true).length;
  const offen = anmeldungen.filter((a) => !a.fields.bezahlt).length;
  const total = anmeldungen.length;
  const pct = total > 0 ? Math.round((bezahlt / total) * 100) : 0;

  return (
    <div className="bg-card rounded-xl shadow-card p-6">
      <div className="flex items-center justify-between mb-5">
        <h3 className="text-base font-700">Zahlungsstatus</h3>
        <Link to="/anmeldungen" className="text-xs text-primary font-600 hover:underline">
          Details →
        </Link>
      </div>
      <div className="flex items-end gap-3 mb-4">
        <span className="text-4xl font-800 text-foreground">{pct}%</span>
        <span className="text-sm text-muted-foreground mb-1.5">bezahlt</span>
      </div>
      <div className="w-full bg-muted rounded-full h-2.5 mb-4">
        <div
          className="h-2.5 rounded-full gradient-card-green transition-all duration-700"
          style={{ width: `${pct}%` }}
        />
      </div>
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-green-50 rounded-lg p-3 text-center">
          <p className="text-xl font-700 text-green-700">{bezahlt}</p>
          <p className="text-xs text-green-600 font-500">Bezahlt</p>
        </div>
        <div className="bg-amber-50 rounded-lg p-3 text-center">
          <p className="text-xl font-700 text-amber-700">{offen}</p>
          <p className="text-xs text-amber-600 font-500">Ausstehend</p>
        </div>
      </div>
    </div>
  );
}

function KurseStatusChart({ kurse }: { kurse: Kurse[] }) {
  const counts = {
    Geplant: kurse.filter((k) => k.fields.status === 'geplant').length,
    Aktiv: kurse.filter((k) => k.fields.status === 'aktiv').length,
    Abgeschlossen: kurse.filter((k) => k.fields.status === 'abgeschlossen').length,
    Abgesagt: kurse.filter((k) => k.fields.status === 'abgesagt').length,
  };
  const data = Object.entries(counts).map(([name, count]) => ({ name, count }));

  const colors: Record<string, string> = {
    Geplant: 'oklch(0.62 0.18 84)',
    Aktiv: 'oklch(0.5 0.15 152)',
    Abgeschlossen: 'oklch(0.45 0.22 264)',
    Abgesagt: 'oklch(0.55 0.2 30)',
  };

  return (
    <div className="bg-card rounded-xl shadow-card p-6">
      <div className="flex items-center justify-between mb-5">
        <h3 className="text-base font-700">Kurse nach Status</h3>
        <div className="flex items-center gap-1.5 bg-muted rounded-lg px-2.5 py-1">
          <TrendingUp size={13} className="text-muted-foreground" />
          <span className="text-xs text-muted-foreground font-500">{kurse.length} gesamt</span>
        </div>
      </div>
      <ResponsiveContainer width="100%" height={180}>
        <BarChart data={data} barSize={36}>
          <CartesianGrid strokeDasharray="3 3" stroke="oklch(0.9 0.01 264)" vertical={false} />
          <XAxis
            dataKey="name"
            tick={{ fontSize: 12, fill: 'oklch(0.52 0.02 264)' }}
            axisLine={false}
            tickLine={false}
          />
          <YAxis
            tick={{ fontSize: 11, fill: 'oklch(0.52 0.02 264)' }}
            axisLine={false}
            tickLine={false}
            allowDecimals={false}
          />
          <Tooltip
            contentStyle={{
              background: 'white',
              border: '1px solid oklch(0.9 0.01 264)',
              borderRadius: '0.75rem',
              fontSize: '12px',
            }}
          />
          <Bar
            dataKey="count"
            radius={[6, 6, 0, 0]}
            fill="oklch(0.45 0.22 264)"
            label={false}
          >
            {data.map((entry) => (
              <rect key={entry.name} fill={colors[entry.name]} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

export default function DashboardOverview() {
  const [stats, setStats] = useState<Stats>({
    dozenten: [],
    teilnehmer: [],
    raeume: [],
    kurse: [],
    anmeldungen: [],
    loading: true,
  });

  useEffect(() => {
    Promise.all([
      LivingAppsService.getDozenten(),
      LivingAppsService.getTeilnehmer(),
      LivingAppsService.getRaeume(),
      LivingAppsService.getKurse(),
      LivingAppsService.getAnmeldungen(),
    ])
      .then(([dozenten, teilnehmer, raeume, kurse, anmeldungen]) => {
        setStats({ dozenten, teilnehmer, raeume, kurse, anmeldungen, loading: false });
      })
      .catch(() => setStats((s) => ({ ...s, loading: false })));
  }, []);

  const { dozenten, teilnehmer, raeume, kurse, anmeldungen, loading } = stats;
  const aktiveKurse = kurse.filter((k) => k.fields.status === 'aktiv').length;
  const today = new Date();
  const bevorstehend = kurse.filter(
    (k) => k.fields.startdatum && isAfter(parseISO(k.fields.startdatum), today)
  ).length;

  return (
    <div className="space-y-8">
      {/* Hero Section */}
      <div className="gradient-hero rounded-2xl p-8 text-white relative overflow-hidden shadow-elevated">
        <div
          className="absolute inset-0 opacity-20"
          style={{
            backgroundImage:
              'radial-gradient(circle at 80% 20%, oklch(0.7 0.18 264) 0%, transparent 60%), radial-gradient(circle at 10% 80%, oklch(0.48 0.16 197) 0%, transparent 50%)',
          }}
        />
        <div className="relative z-10 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-6">
          <div>
            <p className="text-sm font-600 opacity-75 uppercase tracking-widest mb-2">
              Bildungsmanagement
            </p>
            <h1 className="text-3xl lg:text-4xl font-800 tracking-tight leading-tight">
              Kursverwaltungs&shy;system
            </h1>
            <p className="mt-2 opacity-75 text-sm max-w-md">
              Verwalten Sie Ihre Kurse, Dozenten, Teilnehmer und Räume an einem Ort.
            </p>
          </div>
          <div className="grid grid-cols-2 gap-3 lg:flex lg:gap-4 flex-shrink-0">
            <div className="bg-white/10 rounded-xl px-5 py-4 text-center backdrop-blur-sm border border-white/10">
              <p className="text-2xl font-800">{loading ? '—' : aktiveKurse}</p>
              <p className="text-xs opacity-75 mt-0.5">Aktive Kurse</p>
            </div>
            <div className="bg-white/10 rounded-xl px-5 py-4 text-center backdrop-blur-sm border border-white/10">
              <p className="text-2xl font-800">{loading ? '—' : bevorstehend}</p>
              <p className="text-xs opacity-75 mt-0.5">Bevorstehend</p>
            </div>
          </div>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
        <ColoredStatCard
          label="Dozenten"
          value={loading ? '…' : dozenten.length}
          sub="Lehrpersonal"
          icon={GraduationCap}
          gradient="gradient-card-indigo"
          href="/dozenten"
        />
        <ColoredStatCard
          label="Teilnehmer"
          value={loading ? '…' : teilnehmer.length}
          sub="Registriert"
          icon={Users}
          gradient="gradient-card-teal"
          href="/teilnehmer"
        />
        <ColoredStatCard
          label="Räume"
          value={loading ? '…' : raeume.length}
          sub="Verfügbar"
          icon={DoorOpen}
          gradient="gradient-card-green"
          href="/raeume"
        />
        <ColoredStatCard
          label="Kurse"
          value={loading ? '…' : kurse.length}
          sub="Insgesamt"
          icon={BookOpen}
          gradient="gradient-card-amber"
          href="/kurse"
        />
        <ColoredStatCard
          label="Anmeldungen"
          value={loading ? '…' : anmeldungen.length}
          sub="Buchungen"
          icon={CalendarCheck}
          gradient="gradient-card-rose"
          href="/anmeldungen"
        />
      </div>

      {/* Bottom Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <UpcomingKurseCard kurse={kurse} dozenten={dozenten} />
        </div>
        <div className="space-y-6">
          <AnmeldungenStatusCard anmeldungen={anmeldungen} />
        </div>
      </div>

      {/* Chart Row */}
      <KurseStatusChart kurse={kurse} />
    </div>
  );
}

